SELECT s.table_name,s.index_name,s.non_unique,s.seq_in_index,COALESCE(s.column_name,''),COALESCE(s.expression,''),s.collation,COALESCE(s.sub_part,''),s.index_type FROM information_schema.statistics s WHERE s.table_schema='acore_world' AND s.table_name NOT REGEXP '(_locale$|^smart_scripts$|^waypoint|^script_waypoint$|^spell_script_names$|^creature_text$|^updates|^version$|^command$|^acore_string$)' ORDER BY BINARY s.table_name,BINARY s.index_name,s.seq_in_index;
